sealed class CryptoException: kotlin.Exception() {
    
    class Encryption(
        
        val `detail`: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Decryption(
        ) : CryptoException() {
        override val message
            get() = ""
    }
    
    class Kdf(
        
        val `detail`: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class InvalidRecoveryPhrase(
        ) : CryptoException() {
        override val message
            get() = ""
    }
    
    class InvalidInput(
        
        val `detail`: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Opaque(
        
        val `detail`: kotlin.String
        ) : CryptoException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Cancelled(
        ) : CryptoException() {
        override val message
